(()=>{const g=document.getElementById('gross');const eur=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);function update(){const m=Number(g.value),y=m*12,base=Math.min(y,192240)*.9825+Math.max(0,y-192240),gain=base*.026;document.getElementById('gross-value').textContent=eur(m);document.getElementById('employee').textContent='+'+eur(gain/12);document.getElementById('annual').textContent='+'+eur(gain);document.getElementById('employer').textContent='Jusqu’à '+eur(Math.min(y,48060)*.03/12)}g.addEventListener('input',update);update()})();